,p_region_name=>'CONTENT_HOLDER'
,p_region_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'N'
,p_plug_template=>wwv_flow_imp.id(18474261424268418)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_grid_column_css_classes=>'col-sm-12 col-md-10 col-lg-8 div-expand'
,p_plug_item_display_point=>'ABOVE'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT *',
'FROM ',
'    case_folder_session_det cfsd',
'        INNER JOIN session_review sr ON cfsd.case_number = sr.case_number',
'            AND cfsd.session_month = sr.sr_date',
'WHERE',
'    sr.signature_request_hash = :P1_HASH',
