wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(19397671014944551)
,p_plug_name=>'Create Signature'
,p_static_id=>'create-signature'
,p_region_name=>'CREATE_SIG'
,p_parent_plug_id=>wwv_flow_imp.id(15445473304307088)
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'N'
,p_plug_template=>wwv_flow_imp.id(21108186196458681)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_plug_source_type=>'PLUGIN_DE.DANIELH.APEXSIGNATURE'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', '500',
  'attribute_02', '250',
  'attribute_03', '0.5',
  'attribute_04', '2.5',
  'attribute_05', 'rgba(0,0,0,0)',
  'attribute_06', 'black',
  'attribute_07', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    l_clob CLOB;',
    '    l_blob BLOB;',
    '    l_filename VARCHAR2(100);',
    '    l_token VARCHAR2(32000);',
    'BEGIN',
    '    -- build CLOB from f01 30k Array',
    '    dbms_lob.createtemporary(l_clob,',
    '                           FALSE,',
    '                           dbms_lob.session);',
    '',
    '    FOR i IN 1 .. apex_application.g_f01.count LOOP',
    '        l_token := wwv_flow.g_f01(i);',
    '  ',
    '        IF length(l_token) > 0 THEN',
    '            dbms_lob.writeappend(',
    '                l_clob,',
    '                length(l_token),',
    '                l_token);',
    '        END IF;',
    '    END LOOP;',
    '  --',
    '  -- convert base64 CLOB to BLOB (mimetype: image/png)',
    '  l_blob := apex_web_service.clobbase642blob(p_clob => l_clob);',
    '  --',
    '  -- create own collection (here starts custom part (for example a Insert statement))',
    '  UPDATE session_review',
    '  SET reviewer_signature = l_blob,',
    '      reviewer_date = et_sysdate',
    '  WHERE signature_request_hash = :P1_HASH;',
    '  ',
    '  signature_request_complete(:P1_HASH);',
    'END;')),
  'attribute_08', 'false',
  'attribute_09', '#SIG_CLEAR',
  'attribute_10', '#SIG_SAVE',
  'attribute_11', 'Signature must have a value',
  'attribute_12', 'true')).to_clob
);
